import{_ as e,o as a,c as r,a4 as n}from"./chunks/framework.9tZL7ZIQ.js";const u=JSON.parse('{"title":"IBM（International Business Machines Corporation）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/IBM.md","filePath":"03_companies/IBM.md"}'),l={name:"03_companies/IBM.md"};function o(s,t,i,d,c,g){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="ibm-international-business-machines-corporation" tabindex="-1">IBM（International Business Machines Corporation） <a class="header-anchor" href="#ibm-international-business-machines-corporation" aria-label="Permalink to &quot;IBM（International Business Machines Corporation）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>International Business Machines Corporation</td></tr><tr><td>行业</td><td>科技 / IT 服务</td></tr><tr><td>成立年份</td><td>1911年</td></tr><tr><td>总部</td><td>纽约州阿蒙克（Armonk, New York）</td></tr><tr><td>伯克希尔持股</td><td>最高约 <strong>8.5%</strong>（2016年底），2018年几乎全部清仓</td></tr><tr><td>首次买入</td><td><strong>2011年3月</strong>（2010年度股东信公布）</td></tr><tr><td>清仓时间</td><td><strong>2018年</strong></td></tr><tr><td>持仓时间</td><td>约 7 年</td></tr><tr><td>买入成本</td><td>约 <strong>107亿–114亿美元</strong></td></tr><tr><td>最终结果</td><td><strong>亏损</strong>，具体金额未完整披露</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>IBM 是全球最早的科技巨头之一，业务涵盖：</p><ul><li><strong>硬件</strong>：大型计算机（Mainframe）、服务器、存储设备</li><li><strong>软件</strong>：中间件、企业软件（Db2、Cognos、Tivoli 等）</li><li><strong>IT 服务</strong>：咨询、系统集成、外包服务</li><li><strong>云计算</strong>：2010年代转型期间重点发展的方向</li><li><strong>人工智能</strong>：Watson 认知计算平台</li></ul><p>IBM 曾是道琼斯工业平均指数中历史最悠久的成分股（1916年加入，2012年被剔除），见证了整个科技产业的发展变迁。</p><h2 id="与巴菲特的关系" tabindex="-1">与巴菲特的关系 <a class="header-anchor" href="#与巴菲特的关系" aria-label="Permalink to &quot;与巴菲特的关系&quot;">​</a></h2><h3 id="首次买入-迟到派对的入场-2011年" tabindex="-1">首次买入：迟到派对的入场（2011年） <a class="header-anchor" href="#首次买入-迟到派对的入场-2011年" aria-label="Permalink to &quot;首次买入：迟到派对的入场（2011年）&quot;">​</a></h3><p>2011年，巴菲特通过2010年度股东信（2011年3月发布）正式披露：伯克希尔在公开市场买入约 <strong>6,390万股</strong> IBM 股票，总成本约 <strong>109亿美元</strong>（约合当年汇率），一跃成为 IBM 第五大股东，持股比例约 <strong>5.5%</strong>。</p><p>这是巴菲特<strong>首次大规模投资科技股</strong>，打破了他长期回避科技行业的原则。在此之前，他阅读 IBM 年报超过 50 年，但始终未出手，直到2010年3月的一个星期六才&quot; crystallized&quot;（想明白了）。巴菲特引用梭罗的话：&quot;重要的不是你看到什么，而是你看见什么。&quot;</p><blockquote><p>&quot;正如1988年的<a href="/03_companies/可口可乐">可口可乐</a>和2006年的铁路一样，<strong>我参加 IBM 派对晚了</strong>。50多年来我一直在阅读该公司的年度报告，但直到去年3月的一个星期六，我的想法才 crystallized。正如梭罗所说，&#39;重要的不是你看到什么，而是你看见什么。&#39;&quot; —— 2011年致股东信</p></blockquote><p><strong>买入理由：</strong></p><ul><li><strong>转换成本护城河</strong>：企业 IT 系统深度嵌入业务流程，更换供应商的成本和风险极高，理论上形成强大护城河</li><li><strong>定价权</strong>：IBM 的商业模式类似咨询公司，有相对较强的定价权</li><li><strong>回购助力</strong>：IBM 计划未来5年斥资约 <strong>500亿美元</strong>回购股份，这有利于提升股东持股比例</li><li><strong>优秀的管理层</strong>：时任 CEO 彭明盛（Sam Palmisano），以及前 CEO 郭士纳（Lou Gerstner）将 IBM 从破产边缘打造成行业巨头</li><li><strong>卓越的财务管理</strong>：巴菲特认为 IBM 的大型公司中财务管理首屈一指——善用债务、以现金进行增值收购、积极回购股票</li></ul><blockquote><p>&quot;让我们以<a href="/03_companies/IBM">IBM</a>为例。正如所有商业观察者所知道的首席执行官郭士纳（Lou Gerstner）和彭明盛（Sam Palmisano）在过去二十年中将<a href="/03_companies/IBM">IBM</a>从濒临破产的边缘打造成今日的巨头。他们的运营成就确实非同凡响。但他们的财务管理同样出色，尤其近几年来公司的财务灵活性不断提升。确实，<strong>我想不出有哪家大型公司的财务管理比<a href="/03_companies/IBM">IBM</a>更好</strong>，这项技能大幅提升了<a href="/03_companies/IBM">IBM</a>股东的收益。&quot; —— 2011年致股东信</p></blockquote><p><strong>巴菲特还提出了一个反直觉的&quot;祈愿股价低迷&quot;逻辑：</strong></p><blockquote><p>&quot;最终，我们<a href="/03_companies/IBM">IBM</a>投资能否成功将主要取决于其未来的盈利表现。但一个重要的次要因素是，公司用可能投入的这笔巨款能回购多少股份。如果回购最终将<a href="/03_companies/IBM">IBM</a>发行在外的股份减少至6390万股，我将抛弃我著名的节俭作风，给<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>员工放一个带薪假期。&quot; —— 2011年致股东信</p></blockquote><p>算账逻辑：如果股价低迷（~200美元），500亿可回购2.5亿股，5年后巴菲特持股比例将升至约7%；若股价高企（~300美元），则仅回购1.67亿股，比例仅升至6.5%。长期收益差距可达约15亿美元。</p><h3 id="持续增持至顶点-2012–2016年" tabindex="-1">持续增持至顶点（2012–2016年） <a class="header-anchor" href="#持续增持至顶点-2012–2016年" aria-label="Permalink to &quot;持续增持至顶点（2012–2016年）&quot;">​</a></h3><p>巴菲特在随后几年持续增持 IBM：</p><table tabindex="0"><thead><tr><th style="text-align:center;">年份</th><th style="text-align:center;">持股数量（约）</th><th style="text-align:center;">持股比例</th><th style="text-align:center;">成本（百万美元）</th><th style="text-align:center;">市值（百万美元）</th></tr></thead><tbody><tr><td style="text-align:center;">2011</td><td style="text-align:center;">6,390万股</td><td style="text-align:center;">5.5%</td><td style="text-align:center;">$10,856</td><td style="text-align:center;">$11,751</td></tr><tr><td style="text-align:center;">2012</td><td style="text-align:center;">6,811万股</td><td style="text-align:center;">6.0%</td><td style="text-align:center;">$11,680</td><td style="text-align:center;">$13,048</td></tr><tr><td style="text-align:center;">2013</td><td style="text-align:center;">6,812万股</td><td style="text-align:center;">6.3%</td><td style="text-align:center;">$11,681</td><td style="text-align:center;">$12,778</td></tr><tr><td style="text-align:center;">2014</td><td style="text-align:center;">7,697万股</td><td style="text-align:center;"><strong>7.8%</strong></td><td style="text-align:center;">$13,157</td><td style="text-align:center;">$12,349</td></tr><tr><td style="text-align:center;">2015</td><td style="text-align:center;">8,103万股</td><td style="text-align:center;"><strong>8.4%</strong></td><td style="text-align:center;">$13,791</td><td style="text-align:center;">$11,152</td></tr><tr><td style="text-align:center;">2016</td><td style="text-align:center;">8,123万股</td><td style="text-align:center;"><strong>8.5%</strong></td><td style="text-align:center;">$13,815</td><td style="text-align:center;">$13,484</td></tr></tbody></table><p>到2016年底，巴菲特对 IBM 的持仓成本约 <strong>138亿美元</strong>，为整个组合中重要仓位。增持的驱动力主要来自 IBM 的持续股票回购——每增加0.1个百分点持股比例，伯克希尔每年增加约 <strong>5,000万美元</strong>利润。</p><blockquote><p>&quot;选择正确的 CEO 至关重要……同样重要的是他知道自己局限。（正如<a href="/03_companies/IBM">IBM</a>的 Tom Watson, Sr. 所说，&#39;我不是天才，但我在某些地方聪明，我待在这些地方。&#39;）&quot; —— 2014年致股东信</p></blockquote><p>巴菲特也以此警示自己：能力圈有其边界。</p><h3 id="承认错误-2017年" tabindex="-1">承认错误（2017年） <a class="header-anchor" href="#承认错误-2017年" aria-label="Permalink to &quot;承认错误（2017年）&quot;">​</a></h3><p>2017年，巴菲特的态度发生根本性转变。他开始在公开场合承认这笔投资是错误的：</p><blockquote><p>&quot;六年前我买入 IBM 时，我犯了一个大错。六年后，情况更加证明了这一点。&quot; —— 2017年</p></blockquote><blockquote><p>&quot;<strong>我不应该买 IBM。</strong> 你可能想知道我现在是否还持有苹果——是的，我会的。但 IBM，我没有那种确定性。&quot; —— 2017年 CNBC 采访</p></blockquote><p>在2017年股东信中，巴菲特没有在投资表格中提及 IBM 的变动，实际上此时他已开始减持。</p><p><strong>主要失误分析：</strong></p><ol><li><strong>云计算竞争失利</strong>：亚马逊 AWS、微软 Azure 的崛起，从根本上侵蚀了 IBM 的企业 IT 服务市场——企业可以选择&quot;重新建设&quot;而非&quot;替换 IBM&quot;</li><li><strong>转型不及预期</strong>：IBM 的云计算转型速度明显落后于竞争对手</li><li><strong>护城河被高估</strong>：科技行业的变化速度远超预期，&quot;高转换成本&quot;护城河被证明不如想象中坚固</li><li><strong>竞争格局恶化</strong>：传统 IT 服务商普遍承压，IBM 的定价权被进一步压缩</li></ol><blockquote><p>&quot;在其辉煌岁月，通用汽车、IBM、西尔斯罗巴克和美国钢铁雄踞巨大行业。其实力似乎不可动摇。但我痛斥的破坏行为最终导致它们跌至 CEO 和董事不久前认为不可能的深度。它们曾经的财务实力和历史盈利能力证明无防御。&quot; —— 2014年致股东信</p></blockquote><p>这段话在2014年写下时更多是对美国企业的历史性警示，但回头看，正是 IBM 自身命运的写照。</p><h3 id="最终清仓-2018年" tabindex="-1">最终清仓（2018年） <a class="header-anchor" href="#最终清仓-2018年" aria-label="Permalink to &quot;最终清仓（2018年）&quot;">​</a></h3><p>2018年，伯克希尔几乎清仓了全部 IBM 股票。从2016年底的约 8,123万股到2018年的近乎为零，这笔投资以<strong>亏损告终</strong>。</p><blockquote><p>&quot;在 IBM 上，<strong>我低估了竞争的激烈程度</strong>。&quot; —— 2018年致股东信</p></blockquote><p>IBM 从伯克希尔前15大持仓表中<strong>彻底消失</strong>，苹果取而代之成为伯克希尔最大的单一股票持仓（市值约403亿美元）。</p><p>2018年初，巴菲特在接受 CNBC 采访时被问及 IBM 时，明确表示已卖出，而苹果则不同——他对苹果有&quot;确定性&quot;，对 IBM 则没有。</p><p><strong>最终亏损估算：</strong></p><p>从持仓数据推算：</p><ul><li>2016年底持仓成本：约 <strong>138亿美元</strong></li><li>2016年底持仓市值：约 <strong>135亿美元</strong></li><li>持仓期间还收取了部分股息</li><li>最终清仓价格约在130–145美元区间（2018年 IBM 股价区间）</li><li>综合考虑，整体亏损约 <strong>数十亿美元</strong></li></ul><p>这是巴菲特<strong>罕见的公开认错的投资案例</strong>。</p><h2 id="核心竞争优势" tabindex="-1">核心竞争优势 <a class="header-anchor" href="#核心竞争优势" aria-label="Permalink to &quot;核心竞争优势&quot;">​</a></h2><h3 id="_1-高转换成本-曾经" tabindex="-1">1. 高转换成本（曾经） <a class="header-anchor" href="#_1-高转换成本-曾经" aria-label="Permalink to &quot;1. 高转换成本（曾经）&quot;">​</a></h3><ul><li>企业 IT 系统深度嵌入业务流程</li><li>更换供应商的成本和风险极高</li><li>理论上形成强大护城河——但科技变化证明这护城河不够深</li></ul><h3 id="_2-品牌与技术积累" tabindex="-1">2. 品牌与技术积累 <a class="header-anchor" href="#_2-品牌与技术积累" aria-label="Permalink to &quot;2. 品牌与技术积累&quot;">​</a></h3><ul><li>近百年技术积累与专利组合</li><li>在大型机和关键任务系统领域占据主导地位</li><li>全球政府和大型企业客户基础</li></ul><h3 id="_3-服务与咨询能力" tabindex="-1">3. 服务与咨询能力 <a class="header-anchor" href="#_3-服务与咨询能力" aria-label="Permalink to &quot;3. 服务与咨询能力&quot;">​</a></h3><ul><li>企业级 IT 咨询的专业团队</li><li>深入理解客户业务流程</li></ul><h3 id="_4-稳健的财务管理与回购传统" tabindex="-1">4. 稳健的财务管理与回购传统 <a class="header-anchor" href="#_4-稳健的财务管理与回购传统" aria-label="Permalink to &quot;4. 稳健的财务管理与回购传统&quot;">​</a></h3><ul><li>历史上积极进行股票回购</li><li>资本配置能力曾获巴菲特高度评价</li></ul><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><blockquote><p>&quot;正如1988年的<a href="/03_companies/可口可乐">可口可乐</a>和2006年的铁路一样，<strong>我参加 IBM 派对晚了</strong>。50多年来我一直在阅读该公司的年度报告，但直到去年3月的一个星期六，我的想法才 crystallized。&quot; —— 2011年致股东信</p></blockquote><blockquote><p>&quot;确实，<strong>我想不出有哪家大型公司的财务管理比<a href="/03_companies/IBM">IBM</a>更好</strong>。&quot; —— 2011年致股东信</p></blockquote><blockquote><p>&quot;最终，我们<a href="/03_companies/IBM">IBM</a>投资能否成功将主要取决于其未来的盈利表现。但一个重要的次要因素是，公司用可能投入的这笔巨款能回购多少股份。如果回购最终将<a href="/03_companies/IBM">IBM</a>发行在外的股份减少至6390万股，我将抛弃我著名的节俭作风，给<a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a>员工放一个带薪假期。&quot; —— 2011年致股东信</p></blockquote><blockquote><p>&quot;在其辉煌岁月，通用汽车、IBM、西尔斯罗巴克和美国钢铁雄踞巨大行业。其实力似乎不可动摇。但我痛斥的破坏行为最终导致它们跌至 CEO 和董事不久前认为不可能的深度。&quot; —— 2014年致股东信</p></blockquote><blockquote><p>&quot;六年前我买入 IBM 时，我<strong>犯了一个大错</strong>。六年后，情况更加证明了这一点。&quot; —— 2017年 CNBC 采访</p></blockquote><blockquote><p>&quot;<strong>我不应该买 IBM。</strong> 你可能想知道我现在是否还持有苹果——是的，我会的。但 IBM，我没有那种确定性。&quot; —— 2017年 CNBC 采访</p></blockquote><blockquote><p>&quot;在 IBM 上，<strong>我低估了竞争的激烈程度</strong>。&quot; —— 2018年致股东信</p></blockquote><h2 id="财务表现" tabindex="-1">财务表现 <a class="header-anchor" href="#财务表现" aria-label="Permalink to &quot;财务表现&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">年份</th><th style="text-align:center;">持仓（万股）</th><th style="text-align:center;">持股比例</th><th style="text-align:center;">成本（百万美元）</th><th style="text-align:center;">市值（百万美元）</th></tr></thead><tbody><tr><td style="text-align:center;">2011</td><td style="text-align:center;">6,390</td><td style="text-align:center;">5.5%</td><td style="text-align:center;">$10,856</td><td style="text-align:center;">$11,751</td></tr><tr><td style="text-align:center;">2012</td><td style="text-align:center;">6,811</td><td style="text-align:center;">6.0%</td><td style="text-align:center;">$11,680</td><td style="text-align:center;">$13,048</td></tr><tr><td style="text-align:center;">2013</td><td style="text-align:center;">6,812</td><td style="text-align:center;">6.3%</td><td style="text-align:center;">$11,681</td><td style="text-align:center;">$12,778</td></tr><tr><td style="text-align:center;">2014</td><td style="text-align:center;">7,697</td><td style="text-align:center;">7.8%</td><td style="text-align:center;">$13,157</td><td style="text-align:center;">$12,349</td></tr><tr><td style="text-align:center;">2015</td><td style="text-align:center;">8,103</td><td style="text-align:center;">8.4%</td><td style="text-align:center;">$13,791</td><td style="text-align:center;">$11,152</td></tr><tr><td style="text-align:center;">2016</td><td style="text-align:center;">8,123</td><td style="text-align:center;">8.5%</td><td style="text-align:center;">$13,815</td><td style="text-align:center;">$13,484</td></tr><tr><td style="text-align:center;">2017</td><td style="text-align:center;">大幅减持</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td style="text-align:center;">2018</td><td style="text-align:center;"><strong>≈0</strong></td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr></tbody></table><blockquote><p>注：2017–2018年数据未在伯克希尔年报中单独列示（已非重要持仓）。2016年底持仓成本约138亿美元，最终清仓结果为<strong>亏损</strong>，具体金额未完整披露。</p></blockquote><h2 id="相关人物" tabindex="-1">相关人物 <a class="header-anchor" href="#相关人物" aria-label="Permalink to &quot;相关人物&quot;">​</a></h2><ul><li><strong>沃伦·巴菲特</strong>（Warren Buffett）—— 投资者，伯克希尔哈撒韦 CEO</li><li><strong>郭士纳</strong>（Lou Gerstner）—— IBM 前 CEO（1993–2002），将 IBM 从破产边缘挽救</li><li><strong>彭明盛</strong>（Sam Palmisano）—— IBM 前 CEO（2002–2012），巴菲特买入时的掌舵者</li><li><strong>罗睿兰</strong>（Ginni Rometty）—— IBM CEO（2012–2020），巴菲特投资期间 IBM 的掌舵者，云转型的主要推动者</li><li><strong>汤姆·沃森</strong>（Tom Watson, Sr.）—— IBM 传奇创始人，其名言&quot;我不是天才，但我在某些地方聪明，我待在这些地方&quot;被巴菲特引用</li></ul><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p><a href="/search?q=2011年">2011年</a> · <a href="/search?q=2012年">2012年</a> · <a href="/search?q=2013年">2013年</a> · <a href="/search?q=2014年">2014年</a> · <a href="/search?q=2015年">2015年</a> · <a href="/search?q=2016年">2016年</a> · <a href="/search?q=2017年">2017年</a> · <a href="/search?q=2018年">2018年</a></p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a> —— 投资主体</li><li><a href="/03_companies/苹果公司">苹果公司</a> —— IBM 清仓后巴菲特买入的科技股替代（2016年起大举建仓）</li><li><a href="/03_companies/美国运通">美国运通</a> —— 伯克希尔&quot;四大金刚&quot;之一</li><li><a href="/03_companies/可口可乐">可口可乐</a> —— 伯克希尔&quot;四大金刚&quot;之一</li><li><a href="/03_companies/富国银行">富国银行</a> —— 伯克希尔&quot;四大金刚&quot;之一</li><li><a href="/search?q=巴菲特致股东信">巴菲特致股东信</a> —— 历年原始资料来源</li></ul><hr><p><em>最后更新：2026-04-16</em></p><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/01_letters/1962年/翻译">/01_letters/1962年/翻译</a></li><li><a href="/01_letters/1964年/翻译">/01_letters/1964年/翻译</a></li><li><a href="/01_letters/翻译">/01_letters//翻译</a></li><li><a href="/01_letters/翻译">/01_letters//翻译</a></li></ul>',73)])])}const q=e(l,[["render",o]]);export{u as __pageData,q as default};
